using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class RebirthCamperPowerIntegration{
const string Folder="Assets/REBIRTHCamperPowerIntegrated_20261014";const string O="E:/_Haven/shared/REBIRTHTemp/CamperPowerIntegration_20261014";
static Bounds BoundsOf(GameObject o){var rs=o.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
static void Place(GameObject o,Transform parent,Vector3 center,float w,float d){o.transform.SetParent(parent,true);var b=BoundsOf(o);float s=Mathf.Min(w/b.size.x,d/b.size.z);o.transform.localScale*=s;b=BoundsOf(o);o.transform.position+=new Vector3(center.x-b.center.x,center.y-b.min.y,center.z-b.center.z);}
static void Mount(Transform parent,string name,Vector3 center,Vector3 size,Material material){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);UnityEngine.Object.DestroyImmediate(o.GetComponent<Collider>());o.name=name;o.transform.SetParent(parent,false);o.transform.localPosition=center;o.transform.localScale=size;o.GetComponent<MeshRenderer>().sharedMaterial=material;}
static void Render(Camera cam,Vector3 eye,Vector3 target,string label,float size){cam.transform.position=eye;cam.transform.LookAt(target);cam.orthographic=true;cam.orthographicSize=size;var rt=new RenderTexture(1600,1200,24);var im=new Texture2D(1600,1200,TextureFormat.RGB24,false);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;im.ReadPixels(new Rect(0,0,1600,1200),0,0);im.Apply();File.WriteAllBytes(O+"/"+label+".png",im.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(im);}
static void Review(GameObject root,List<string> report){var power=root.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="REBIRTHCampPowerEquipment");RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.65f,.65f);var key=new GameObject("Key").AddComponent<Light>();key.type=LightType.Directional;key.transform.rotation=Quaternion.Euler(45,0,0);key.intensity=1.1f;var fill=new GameObject("Fill").AddComponent<Light>();fill.type=LightType.Directional;fill.transform.rotation=Quaternion.Euler(30,130,0);fill.intensity=.45f;var cam=new GameObject("Camera").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.12f,.14f,.16f);cam.nearClipPlane=.01f;
foreach(var r in root.GetComponentsInChildren<Renderer>(true).Where(r=>r.name=="body"||r.name=="camper_body")){var b=new MaterialPropertyBlock();b.SetFloat("_PatternEnabled",1);r.SetPropertyBlock(b);}
foreach(bool camp in new[]{false,true}){RebirthCamperCampIntegration.SetMode(root,camp);power.gameObject.SetActive(camp);int n=power.GetComponentsInChildren<Renderer>(true).Count(r=>r.enabled&&r.gameObject.activeInHierarchy);if(camp&&n!=9||!camp&&n!=0)throw new Exception("Power visibility failure "+n);Physics.SyncTransforms();if(camp)for(float z=-3.75f;z<=-2.95f;z+=.05f)if(Physics.CheckCapsule(new Vector3(0,1.03f,z),new Vector3(0,1.55f,z),.29f))throw new Exception("Power obstructed entry");report.Add((camp?"Camp":"Travel")+" power renderers="+n+"; entry capsule="+(camp?"PASS":"N/A"));Render(cam,new Vector3(-4,5,-6),new Vector3(0,1.7f,-1.2f),(camp?"camp":"travel")+"-full",3.6f);Render(cam,new Vector3(-3.6f,3.9f,-6),new Vector3(0,2.25f,-2.8f),(camp?"camp":"travel")+"-power-detail",1.8f);}
}
public static void RunBatch(){Directory.CreateDirectory(O);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);try{var report=new List<string>();var root=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/REBIRTHCamperCampIntegrated_20261014/rebirthCamper80s.prefab"));root.name="rebirthCamper80s";var group=new GameObject("REBIRTHCampPowerEquipment").transform;group.SetParent(root.transform.Find("GameObject/M/VisualBody"),false);var battery=RebirthImportedStationsReview.Import("industrial+battery+pack");Place(battery,group,new Vector3(-.58f,2.01f,-3.53f),.56f,.32f);var generator=RebirthImportedStationsReview.Import("rusty+industrial+generator");Place(generator,group,new Vector3(.58f,2.01f,-3.53f),.56f,.32f);var solar=RebirthImportedStationsReview.Import("solar+panel");Place(solar,group,new Vector3(0,2.51f,-3.47f),1.50f,.50f);foreach(var obj in new[]{battery,generator,solar}){var b=BoundsOf(obj);report.Add(obj.name+" bounds="+b);long tris=obj.GetComponentsInChildren<MeshFilter>().Sum(f=>(long)f.sharedMesh.triangles.Length/3);report.Add(obj.name+" triangles="+tris);if(obj!=solar&&b.max.y>2.47f)throw new Exception("Rear power model exceeds mounting height");}
var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/REBIRTHStationAddons/ImportedStations_20261014/Guardrail.mat");foreach(float x in new[]{-.58f,.58f}){Mount(group,"Rear power shelf",new Vector3(x,1.995f,-3.51f),new Vector3(.59f,.025f,.35f),mat);Mount(group,"Rear power mount",new Vector3(x,2.075f,-3.342f),new Vector3(.44f,.16f,.022f),mat);}foreach(float x in new[]{-.55f,.55f})Mount(group,"Solar roof mount",new Vector3(x,2.496f,-3.43f),new Vector3(.055f,.025f,.48f),mat);
foreach(string name in new[]{"industrial+battery+pack","rusty+industrial+generator","solar+panel"})foreach(var p in AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith("Assets/REBIRTHStationAddons/ImportedStations_20261014/"+name+"/"))){var t=AssetImporter.GetAtPath(p) as TextureImporter;if(t==null)continue;t.maxTextureSize=2048;t.textureCompression=TextureImporterCompression.CompressedHQ;t.mipmapEnabled=true;t.isReadable=false;t.SaveAndReimport();}
group.gameObject.SetActive(false);PrefabUtility.SaveAsPrefabAsset(root,Folder+"/rebirthCamper80s.prefab");AssetDatabase.SaveAssets();Review(root,report);File.WriteAllLines(O+"/receipt.txt",report);}catch(Exception e){File.WriteAllText(O+"/failure.txt",e.ToString());throw;}}
public static void VerifyBuiltBatch(){Directory.CreateDirectory(O);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var b=AssetBundle.LoadFromFile(O+"/Bundle/rebirth_camper80s.unity3d");if(!b)throw new Exception("Bundle missing");try{var root=UnityEngine.Object.Instantiate(b.LoadAsset<GameObject>("rebirthCamper80s"));var p=root.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="REBIRTHCampPowerEquipment");if(p.gameObject.activeSelf)throw new Exception("Default power visible");foreach(var r in p.GetComponentsInChildren<Renderer>(true))foreach(var m in r.sharedMaterials)foreach(string key in m.GetTexturePropertyNames()){var t=m.GetTexture(key);if(t&&(t.width>2048||t.height>2048))throw new Exception("Power texture exceeds2K");}var report=new List<string>();Review(root,report);report.Add("Reopened final power bundle PASS; actual gameplay not tested.");File.WriteAllLines(O+"/bundle-proof.txt",report);}finally{b.Unload(false);}}
}
